"""Extra scenarios (Phase 4). Run tools/build_scenarios.py to merge into web/data/content.json.
Compact form: S(id, skill, setting, pressure, title, context, line, situation, moves, topic, question,
models[2], passes[1+], fails[1+], **options). Settings: 1:1, client, interview, standup, appraisal, email, meeting."""

def S(id, skill, setting, pressure, title, context, line, situation, moves, topic, question, models, passes, fails, **kw):
    d = dict(id=id, skill=skill, setting=setting, pressure=pressure, title=title, context=context, line=line, situation=situation,
             moves=moves, topic=topic, question=question, models=models, tests={"pass": passes, "fail": fails})
    d.update(kw)
    return d

def F(pattern, message, fix, habit):
    return {"pattern": pattern, "message": message, "fix": fix, "habit": habit}

CLEAR_ASK = {"label": "Clear ask", "patterns": [r"\b(could|can|would) you\b", r"\bplease\b", r"\b(could|can|may) (i|we)\b[^?.!]*\?"], "tip": "Put the ask in the first line."}
EVID = {"label": "Evidence", "patterns": [r"\d", r"\b(tested|checked|data|numbers?|logs?|feedback|results?|measured|saw|noticed|emails?|according to|records?|timeline|couldn't|struggled)\b"], "tip": "Back it up with something concrete."}
CONSTRAINT = {"label": "State your constraint", "patterns": [r"\b(currently|right now|this week|my plate|working on|committed to|bandwidth|capacity|due|deadline|approval|our process|policy)\b"], "tip": "Say what you're already committed to."}
CHOICE = {"label": "Let them choose", "patterns": [r"\bwhich (one )?(should|would|do)\b", r"\bprioriti[sz]e\b", r"\beither\b.*\bor\b", r"\bor\b[^.?!]*\?", r"\bnext week\b"], "tip": "Offer a choice of priorities."}
ACHIEVE = {"label": "Concrete achievement", "patterns": [r"\d", r"\b(delivered|shipped|led|built|reduced|improved|saved|launched|fixed|automated)\b"], "tip": "Name a result with a number."}
HYPO = {"label": "Label guesses as guesses", "patterns": [r"\b(could be|might be|may be|one possibility|my guess|hypothes|hunch|possibly|it's possible|suspect)\b"], "tip": "\"One possibility is...\""}
PREVENT = {"label": "Prevent it next time", "patterns": [r"\b(going forward|next time|from now on|to avoid|to prevent|double[- ]?check|checklist|won't happen|in future|in the future|alert|test for)\b"], "tip": "Say what you'll change."}
REF = {"label": "Reference the earlier message", "patterns": [r"\b(following up|circling back|checking in|my (last|previous|earlier) (email|message|mail)|on my (email|message))\b"], "tip": "\"Following up on my email from Monday...\""}
FLOOR = {"label": "Keep the floor politely", "patterns": [r"\b(let me|i'd like to|can i|allow me to|i want to) (just )?(finish|complete|wrap up|close|add)", r"\bone (second|moment|sec)\b", r"\bbefore we move on\b", r"\bif i (may|could) (finish|add)\b"], "tip": "\"Let me finish this point...\""}

